package com.finsight;
import java.time.*;
import java.math.BigDecimal;
import java.util.*;
import java.util.regex.Pattern;
import org.springframework.stereotype.Service;
import static com.finsight.AssistantModels.*;
@Service
class SavingsAssistant {
 private final SavingsService savings;private final Clock clock;
 SavingsAssistant(SavingsService savings,Clock clock){this.savings=savings;this.clock=clock;}
 Answer answer(String question){String q=question.toLowerCase(Locale.ROOT);var goals=savings.list();if(q.contains("last month")||q.contains("this month")||AssistantParser.ISO.matcher(q).find())return clarify("Savings questions currently report the goal's current allocations and stored target. Use Savings Goals history for date-specific allocation activity.");if(goals.isEmpty())return clarify("No savings goals are recorded. The assistant cannot create goals; use Savings Goals to create one explicitly.");List<SavingsModels.Goal> selected;
 if(q.contains("closest")){var active=goals.stream().filter(g->!g.archived()&&!g.completed()).toList();if(active.isEmpty())return clarify("No active incomplete savings goals are recorded.");var best=active.stream().map(g->new BigDecimal(g.progress())).max(BigDecimal::compareTo).orElseThrow();selected=active.stream().filter(g->new BigDecimal(g.progress()).compareTo(best)==0).toList();}
 else {selected=goals.stream().filter(g->Pattern.compile("(?<![a-z0-9])"+Pattern.quote(g.name().toLowerCase(Locale.ROOT))+"(?![a-z0-9])").matcher(q).find()).toList();if(selected.isEmpty()&&goals.size()==1&&(q.contains("my savings goal")||q.contains("my target")))selected=goals;if(selected.size()!=1)return clarify("Please name one exact savings goal. Available goals: "+String.join(", ",goals.stream().map(SavingsModels.Goal::name).toList())+". Duplicate names need clarification in Savings Goals.");}
 List<Metric> metrics=new ArrayList<>();List<Evidence> evidence=new ArrayList<>();List<String> assumptions=new ArrayList<>();StringBuilder text=new StringBuilder();boolean estimate=q.contains("when")||q.contains("each month")||q.contains("per month")||q.contains("should i save");
 for(var g:selected){var d=savings.detail(g.id());text.append(g.name()).append(": $").append(g.saved()).append(" allocated toward $").append(g.targetAmount()).append("; $").append(g.remaining()).append(" remaining. ");metrics.add(new Metric(g.name()+" allocated",g.saved()));metrics.add(new Metric(g.name()+" remaining",g.remaining()));metrics.add(new Metric(g.name()+" progress percent",g.progress()));if(estimate){var p=d.projection();text.append(p.estimatedCompletionDate()==null?"No supported completion estimate. ":"Estimated allocation completion: "+p.estimatedCompletionDate()+". ");metrics.add(new Metric(g.name()+" required monthly",p.requiredMonthly()));metrics.add(new Metric(g.name()+" expected by target",p.expectedByTarget()));assumptions.addAll(p.observations());}for(var e:d.entries().stream().filter(SavingsModels.Entry::active).limit(30).toList())evidence.add(new Evidence(e.id().toString(),e.note().isBlank()?g.name()+" allocation":e.note(),e.amount(),e.type().name(),e.date(),e.bucket().name(),"SAVINGS_ALLOCATION"));}
 assumptions.add("Calculation source: SavingsService. Allocations are separate from bank transactions, spending and income. Money tracked outside this account is not reserved again from its balance. Forecasts are conditional; the assistant performs no writes.");if(q.contains("closest"))assumptions.add("Closest uses the highest displayed progress percentage among active incomplete goals. Equal rounded percentages are returned together.");int total=selected.stream().mapToInt(g->(int)savings.detail(g.id()).entries().stream().filter(SavingsModels.Entry::active).count()).sum();return new Answer("answered","deterministic",estimate?"ALLOCATION_ESTIMATE":"ACTUAL_ALLOCATION","Savings goals",text.toString(),LocalDate.now(clock),null,null,metrics,evidence.stream().limit(30).toList(),total,assumptions,List.of(new Link("Savings Goals","#savings")),List.of("Which savings goal is closest to completion?","When will I reach my savings goal?"),null);
 }
 private Answer clarify(String text){return new Answer("clarification","deterministic","LIMITATION","Savings goal clarification",text,LocalDate.now(clock),null,null,List.of(),List.of(),0,List.of("No savings or bank records were changed."),List.of(new Link("Savings Goals","#savings")),List.of(),null);}
}
